#include <iostream>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int total;
    std::cin >> total;
    std::string inputStr;
    std::cin >> inputStr;

    // Replace all underscores with spaces
    for (char &ch : inputStr) {
        if (ch == '_') {
            ch = ' ';
        }
    }

    // Insert spaces around parentheses
    std::string processed;
    for (char ch : inputStr) {
        if (ch == '(') {
            processed += " ( ";
        } else if (ch == ')') {
            processed += " ) ";
        } else {
            processed += ch;
        }
    }

    // Split the processed string into tokens
    std::istringstream iss(processed);
    std::string token;
    int maxLength = 0;
    int parenthesesCount = 0;
    bool insideParentheses = false;

    while (iss >> token) {
        if (token.find('(') != std::string::npos) {
            insideParentheses = true;
        } else if (token.find(')') != std::string::npos) {
            insideParentheses = false;
        } else if (token.find('(') == std::string::npos && token.find(')') == std::string::npos) {
            if (insideParentheses) {
                parenthesesCount++;
            } else {
                maxLength = std::max(maxLength, static_cast<int>(token.length()));
            }
        }
    }

    std::cout << maxLength << " " << parenthesesCount << std::endl;
    return 0;
}
